const KEY_FIELDS = ["article_id","source","source_tier","published_at","headline","body","truth_subjects","truth_industries","truth_geographies","truth_entities","trap","duplicate_of","key_version"];
function fnv(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
const norm = v => v === null || v === undefined ? '' : String(v);
const seenIds = new Set();
const changed = [], added = [];
for (const r of rows) {
  const id = norm(r.article_id);
  seenIds.add(id);
  const h = fnv(KEY_FIELDS.map(f => norm(r[f])).join('\u0001'));
  if (!(id in KEY_HASHES)) added.push(id); else if (KEY_HASHES[id] !== h) changed.push(id);
}
const missing = Object.keys(KEY_HASHES).filter(id => !seenIds.has(id));
if (changed.length || added.length || missing.length) {
  throw new Error('Golden key changed since it was frozen. changed: [' + changed.join(', ') + '] added: [' + added.join(', ') + '] missing: [' + missing.join(', ') + ']');
}
const split = s => norm(s).split(',').map(x => x.trim()).filter(Boolean);

const order = id => (id[0] === 'A' ? 0 : 1000) + Number(id.slice(1));
rows.sort((a, b) => order(a.article_id) - order(b.article_id));
const ARTICLES = rows.map(r => ({
  article_id: r.article_id, source: r.source, source_tier: Number(r.source_tier), published_at: r.published_at,
  headline: r.headline, body: r.body,
  truth_subjects: split(r.truth_subjects), truth_industries: split(r.truth_industries),
  truth_geographies: split(r.truth_geographies), truth_entities: split(r.truth_entities),
  trap: r.trap,
}));


// Ingest-time near-duplicate detection. Wire copy is re-published verbatim across
// outlets; tagging the same story twice is pure re-work and pollutes counts.
function normalize(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function shingles(s) {
  const w = normalize(s).split(' ');
  const out = [];
  for (let i = 0; i + 5 <= w.length; i++) out.push(w.slice(i, i + 5).join(' '));
  return out;
}
function jaccard(a, b) {
  const A = new Set(a);
  const B = new Set(b);
  let inter = 0;
  A.forEach(x => { if (B.has(x)) inter++; });
  const uni = A.size + B.size - inter;
  return uni === 0 ? 0 : inter / uni;
}

const SIM_THRESHOLD = 0.50;
const sigs = ARTICLES.map(a => shingles(a.headline + ' ' + a.body));
const clusterOf = new Array(ARTICLES.length).fill(-1);
let nextCluster = 0;
for (let i = 0; i < ARTICLES.length; i++) {
  if (clusterOf[i] !== -1) continue;
  clusterOf[i] = nextCluster;
  for (let j = i + 1; j < ARTICLES.length; j++) {
    if (clusterOf[j] !== -1) continue;
    if (jaccard(sigs[i], sigs[j]) >= SIM_THRESHOLD) clusterOf[j] = nextCluster;
  }
  nextCluster++;
}

// Canonical = best available version: lowest source tier wins, then longest body,
// then earliest timestamp. A tier-1 wire beats a tier-3 rewrite.
const canonicalIdx = {};
for (let i = 0; i < ARTICLES.length; i++) {
  const c = clusterOf[i];
  const cur = canonicalIdx[c];
  if (cur === undefined) { canonicalIdx[c] = i; continue; }
  const a = ARTICLES[i];
  const b = ARTICLES[cur];
  if (a.source_tier < b.source_tier) { canonicalIdx[c] = i; continue; }
  if (a.source_tier === b.source_tier && a.body.length > b.body.length) { canonicalIdx[c] = i; continue; }
  if (a.source_tier === b.source_tier && a.body.length === b.body.length && a.published_at < b.published_at) canonicalIdx[c] = i;
}

const clusterSize = {};
for (let i = 0; i < ARTICLES.length; i++) {
  clusterSize[clusterOf[i]] = (clusterSize[clusterOf[i]] || 0) + 1;
}

// Routing policy. Thresholds are configuration, not code: an editorial lead
// tunes these per facet without touching the pipeline.
// auto_publish_min_confidence is tested against the LEAD tag of each required
// facet, not the minimum across every tag. Broader-term roll-ups are correctly
// tagged at lower confidence, and gating on the minimum sent 87.5% of a clean
// queue to human review in the first calibration run.
const POLICY = {
  auto_publish_min_confidence: 0.85,
  review_floor_confidence: 0.60,
  provisional_below: 0.75,
  max_tags_per_facet: 4,
  required_facets: ['SUBJECT', 'INDUSTRY'],
  require_verbatim_evidence: true,
};

return ARTICLES.map((a, idx) => {
  const cid = 'CL-' + String(clusterOf[idx] + 1).padStart(3, '0');
  return {
    json: {
      article_id: a.article_id,
      source: a.source,
      source_tier: a.source_tier,
      published_at: a.published_at,
      headline: a.headline,
      body: a.body,
      truth_subjects: a.truth_subjects,
      truth_industries: a.truth_industries,
      truth_geographies: a.truth_geographies,
      truth_entities: a.truth_entities,
      trap: a.trap,
      cluster_id: cid,
      cluster_size: clusterSize[clusterOf[idx]],
      is_canonical: canonicalIdx[clusterOf[idx]] === idx,
      canonical_article_id: ARTICLES[canonicalIdx[clusterOf[idx]]].article_id,
      vocab: VOCAB,
      vocab_block: VOCAB_BLOCK,
      entity_master: ENTITY_MASTER,
      policy: POLICY,
      queue_size: ARTICLES.length,
    },
  };
});

const item = $input.item.json;
const text = item.headline + '\n\n' + item.body;

// Common nouns that turn a company alias into an ordinary word.
// "Shell plc" is an entity; "shell companies" is not.
const COMMON_NOUN_AFTER = /^\s+(compan(y|ies)|corporat(e|ion|ions)|entit(y|ies)|firm|firms|structure|structures|game|games|script|scripts|account|accounts)\b/i;

function escapeRe(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function findMentions(surface) {
  const s = String(surface);
  // A trailing \b after a non-word character (as in "Pfizer Inc.") can never match,
  // which would silently downgrade every full legal name to a weak alias hit.
  const lead = /^\w/.test(s) ? '\\b' : '';
  const trail = /\w$/.test(s) ? '\\b' : '';
  const re = new RegExp(lead + escapeRe(s) + trail, 'g');
  const hits = [];
  let m = re.exec(text);
  while (m !== null) {
    const tail = text.slice(m.index + m[0].length, m.index + m[0].length + 24);
    if (!COMMON_NOUN_AFTER.test(tail)) {
      hits.push({ offset: m.index, surface: m[0] });
    }
    m = re.exec(text);
  }
  return hits;
}

// Deterministic entity candidate generation against the authority file.
// Full legal name and ticker are high-precision; bare aliases are weaker evidence.
const candidates = [];
for (const ent of item.entity_master) {
  const byName = findMentions(ent.name);
  const byTicker = ent.ticker && /^[A-Z.0-9]+$/.test(ent.ticker) ? findMentions(ent.ticker) : [];
  let byAlias = [];
  for (const al of ent.aliases) {
    byAlias = byAlias.concat(findMentions(al));
  }
  const total = byName.length + byTicker.length + byAlias.length;
  if (total === 0) continue;
  const firstOffset = Math.min(
    ...[].concat(byName, byTicker, byAlias).map(h => h.offset)
  );
  candidates.push({
    entity_id: ent.entity_id,
    name: ent.name,
    ticker: ent.ticker,
    match_strength: byName.length > 0 || byTicker.length > 0 ? 'strong' : 'alias_only',
    mention_count: total,
    first_offset: firstOffset,
    in_headline: firstOffset < item.headline.length,
  });
}
candidates.sort((a, b) => a.first_offset - b.first_offset);

// v2 (Golden 500): Elevance is a health insurer, which the vocabulary files under two
// industries. Without this note the model tagged IND-INSUR only and set IND-HEALTH
// aside at 0.30-0.55 (4 silent errors in exec 68).
const ENTITY_NOTES = {
  'CO-0012': 'a health insurer (payer): when it is primary, the story is IND-HEALTH (Healthcare Providers & Payers) as well as IND-INSUR',
};

const candidateBlock = candidates.length === 0
  ? '  (none matched the authority file)'
  : candidates.map(c =>
      '  ' + c.entity_id + ' = ' + c.name + ' [' + c.match_strength +
      ', ' + c.mention_count + ' mention(s)' + (c.in_headline ? ', appears in headline' : '') + ']' +
      (ENTITY_NOTES[c.entity_id] ? ' - ' + ENTITY_NOTES[c.entity_id] : '')
    ).join('\n');

// Rule 4 carries two separate instructions that an earlier revision merged into
// one. Merging them cost 16 points of SUBJECT recall: the model read "most
// specific code" as "one code" and dropped co-equal secondary subjects.
const prompt =
  'You are an indexing analyst for a global news and business content operation. ' +
  'You assign controlled-vocabulary metadata to incoming articles so they can be retrieved by legal and business researchers.\n\n' +
  'RULES\n' +
  '1. Every code you return MUST be copied exactly from the vocabulary below. Never invent a code, never modify one, never return a code that is not listed.\n' +
  '2. For every code you return, quote the exact span of the article that justifies it. Copy the span verbatim, character for character. Do not paraphrase.\n' +
  '3. If no listed code applies to a facet, return an empty array for that facet. An empty facet is a correct and useful answer. Guessing is not.\n' +
  '4. Return EVERY distinct subject the story is about, not just one. A single article is often several things at once - an environmental matter that is also a regulatory action and also litigation - and each of those is a separate code. BUT for each subject you identify, return only its MOST SPECIFIC code, never also its broader term. If you tag SUBJ-PAT, do not also tag SUBJ-IP; the pipeline adds broader terms from the taxonomy itself. Two codes that are genuinely different subjects both belong; a code and its own ancestor do not. The broader term of a code is ONLY the one shown as "narrower term of" in the vocabulary; codes without that note have no broader term.\n' +
  '4a. SUBJ-REG (Regulation & Compliance) is its own subject, and it sits ALONGSIDE other subjects rather than being replaced by them. Tag SUBJ-REG in addition to the specific subject whenever a government or public body - a regulator, agency, commission, ministry, inspectorate, tax authority, central bank, prosecutor or enforcement office, or a local government acting in an official capacity - fines, penalises, assesses, audits, investigates, licenses, approves, orders, recalls or settles with a company, or when a company discloses such action or reports itself to authorities. For example: a tax authority reassessment is SUBJ-TAX and SUBJ-REG; an environmental agency fine is SUBJ-ENV and SUBJ-REG; an anti-money-laundering penalty is SUBJ-AML and SUBJ-REG; a bribery settlement with a justice department is SUBJ-BRIBE and SUBJ-REG; a recall announced through a safety agency is SUBJ-PROD and SUBJ-REG. Do not tag SUBJ-REG for a company merely mentioning that it is regulated.\n' +
  '4b. Tag SUBJ-LIT whenever a court is part of the story - a lawsuit, claim filed in court, appeal, judgment, verdict, injunction, court order, or a settlement or agreement approved by a judge - even when another subject (tax, IP, insolvency, bribery) is the main one. Tag SUBJ-CLASS instead when it is a class action (the pipeline adds SUBJ-LIT). An administrative proceeding before an agency with no court involved is not SUBJ-LIT.\n' +
  '5. Return at most ' + item.policy.max_tags_per_facet + ' codes per facet, ordered most to least central to the story.\n' +
  '6. confidence is your probability that a senior editor would keep the code. Use the full range. Be honest about weak evidence.\n\n' +
  'CONTROLLED VOCABULARY\n' + item.vocab_block + '\n\n' +
  'COMPANY AUTHORITY CANDIDATES DETECTED IN THIS TEXT\n' + candidateBlock + '\n' +
  'For each candidate decide role: "primary" if the company is a subject of the story, ' +
  '"passing" if it appears only as background, a former employer, a comparison, or a list member. ' +
  'Do not add companies that are not in the candidate list.\n\n' +
  'ARTICLE\n' +
  'HEADLINE: ' + item.headline + '\n' +
  'BODY: ' + item.body + '\n\n' +
  'For uncoded_note: return a sentence ONLY if a CENTRAL subject or industry of this story has no code in the vocabulary at all. ' +
  'Do not report uncodeable details such as figures, dates, party names, or sub-aspects of a concept that is already coded. ' +
  'Most articles should return an empty string. This field feeds a taxonomy change request, so a false positive costs a taxonomist real time.\n\n' +
  'Respond with ONLY valid JSON, no preamble and no code fences, in exactly this shape:\n' +
  '{"subject_codes":[{"code":"SUBJ-XXX","confidence":0.0,"evidence":"verbatim span from the article"}],' +
  '"industry_codes":[{"code":"IND-XXX","confidence":0.0,"evidence":"verbatim span"}],' +
  '"geography_codes":[{"code":"GEO-XXX","confidence":0.0,"evidence":"verbatim span"}],' +
  '"companies":[{"entity_id":"CO-0000","role":"primary","confidence":0.0,"evidence":"verbatim span"}],' +
  '"uncoded_note":""}';

return {
  json: {
    ...item,
    entity_candidates: candidates,
    prompt,
  },
};

const src = $('Layer 1 Structural Scan').item.json;
const resp = $input.item.json;
const policy = src.policy;

const VOCAB_BY_CODE = {};
for (const v of src.vocab) VOCAB_BY_CODE[v.code] = v;

let parsed = null;
let llm_status = 'ok';
let usage = { input_tokens: 0, output_tokens: 0 };

try {
  if (resp.error) throw new Error(resp.error.message || 'api error');
  const blocks = Array.isArray(resp.content) ? resp.content : [];
  const textBlock = blocks.find(b => b && b.type === 'text');
  const raw = textBlock && textBlock.text;
  if (!raw) throw new Error('no text block in response (blocks: ' + blocks.map(b => b && b.type).join(',') + ')');
  usage = resp.usage || usage;
  const cleaned = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  llm_status = 'error: ' + e.message;
}

const articleText = src.headline + ' ' + src.body;
const haystack = articleText.toLowerCase().replace(/\s+/g, ' ');

function isGrounded(evidence) {
  if (!evidence) return false;
  const needle = String(evidence).toLowerCase().replace(/\s+/g, ' ').trim();
  if (needle.length < 8) return false;
  return haystack.indexOf(needle) !== -1;
}

// Hierarchy is a property of the taxonomy, not a judgement call for the model.
function ancestorsOf(code) {
  const out = [];
  let cur = VOCAB_BY_CODE[code];
  let hops = 0;
  while (cur && cur.broader && VOCAB_BY_CODE[cur.broader] && hops < 8) {
    if (out.indexOf(cur.broader) === -1) out.push(cur.broader);
    cur = VOCAB_BY_CODE[cur.broader];
    hops++;
  }
  return out;
}

function rollUp(tags) {
  const out = tags.slice();
  for (const t of tags) {
    for (const anc of ancestorsOf(t.code)) {
      if (!out.find(x => x.code === anc)) {
        out.push({
          code: anc,
          label: VOCAB_BY_CODE[anc].label,
          confidence: t.confidence,
          provisional: t.provisional,
          inherited_from: t.code,
          evidence: t.evidence,
        });
      }
    }
  }
  return out;
}

function closure(codes) {
  const out = [];
  for (const c of codes || []) {
    if (out.indexOf(c) === -1) out.push(c);
    for (const a of ancestorsOf(c)) if (out.indexOf(a) === -1) out.push(a);
  }
  return out;
}

const rejections = [];
const remaps = [];

// LAYER 3A - conformance guard.
// Answers "is every tag on this record allowed?"
function guardFacet(proposed, facet) {
  const kept = [];
  for (const t of Array.isArray(proposed) ? proposed : []) {
    const code = String(t && t.code || '').trim();
    const conf = typeof t.confidence === 'number' ? t.confidence : 0;
    const entry = VOCAB_BY_CODE[code];

    if (!entry) {
      rejections.push({ facet, code, reason: 'HALLUCINATED_CODE', detail: 'not present in the controlled vocabulary', confidence: conf });
      continue;
    }
    if (entry.facet !== facet) {
      rejections.push({ facet, code, reason: 'FACET_MISMATCH', detail: 'belongs to facet ' + entry.facet, confidence: conf });
      continue;
    }
    if (policy.require_verbatim_evidence && !isGrounded(t.evidence)) {
      rejections.push({ facet, code, reason: 'UNGROUNDED_EVIDENCE', detail: 'quoted span does not appear in the article', confidence: conf, evidence: t.evidence });
      continue;
    }

    let finalCode = code;
    if (entry.status === 'deprecated') {
      if (!entry.replaced_by || !VOCAB_BY_CODE[entry.replaced_by]) {
        rejections.push({ facet, code, reason: 'DEPRECATED_NO_SUCCESSOR', detail: 'retired code with no mapping', confidence: conf });
        continue;
      }
      finalCode = entry.replaced_by;
      remaps.push({ facet, from: code, to: finalCode, reason: 'DEPRECATED_REMAPPED' });
    }
    if (conf < policy.review_floor_confidence) {
      rejections.push({ facet, code: finalCode, reason: 'BELOW_CONFIDENCE_FLOOR', detail: 'confidence ' + conf + ' < ' + policy.review_floor_confidence, confidence: conf });
      continue;
    }
    if (kept.find(k => k.code === finalCode)) continue;
    kept.push({
      code: finalCode,
      label: VOCAB_BY_CODE[finalCode].label,
      confidence: conf,
      provisional: conf < (policy.provisional_below || 0.75),
      evidence: t.evidence,
    });
  }

  kept.sort((a, b) => b.confidence - a.confidence);
  if (kept.length > policy.max_tags_per_facet) {
    for (const cut of kept.slice(policy.max_tags_per_facet)) {
      rejections.push({ facet, code: cut.code, reason: 'FACET_CAP_EXCEEDED', detail: 'beyond ' + policy.max_tags_per_facet + ' codes', confidence: cut.confidence });
    }
  }
  return rollUp(kept.slice(0, policy.max_tags_per_facet));
}

const subjects = llm_status === 'ok' ? guardFacet(parsed.subject_codes, 'SUBJECT') : [];
const industries = llm_status === 'ok' ? guardFacet(parsed.industry_codes, 'INDUSTRY') : [];
const geographies = llm_status === 'ok' ? guardFacet(parsed.geography_codes, 'GEOGRAPHY') : [];

const candidateIds = src.entity_candidates.map(c => c.entity_id);
const entities = [];
if (llm_status === 'ok') {
  for (const c of Array.isArray(parsed.companies) ? parsed.companies : []) {
    const id = String(c && c.entity_id || '').trim();
    if (!candidateIds.includes(id)) {
      rejections.push({ facet: 'COMPANY', code: id, reason: 'ENTITY_NOT_IN_CANDIDATES', detail: 'not matched by the authority file', confidence: c.confidence || 0 });
      continue;
    }
    if (c.role !== 'primary') continue;
    if ((c.confidence || 0) < policy.review_floor_confidence) {
      rejections.push({ facet: 'COMPANY', code: id, reason: 'BELOW_CONFIDENCE_FLOOR', detail: 'confidence ' + c.confidence, confidence: c.confidence || 0 });
      continue;
    }
    const master = src.entity_candidates.find(x => x.entity_id === id);
    if (!entities.find(e => e.entity_id === id)) {
      entities.push({ entity_id: id, name: master.name, confidence: c.confidence, evidence: c.evidence });
    }
  }
}

const appliedSubject = subjects.map(t => t.code);
const appliedIndustry = industries.map(t => t.code);
const appliedGeography = geographies.map(t => t.code);

// LAYER 3B - completeness cues.
// The conformance guard cannot answer "is a tag MISSING?". A record with three
// correct tags and one omission passes every membership test, and omissions
// were the entire silent-error population in run 4. These cues are high-recall
// and deliberately dumb. They never ADD a tag - adding one would put an
// unreviewed guess in the index, which is the thing this pipeline exists to
// prevent. They only refuse to auto-publish, so precision is untouched and the
// cost is paid in editor time, which is a dial the business can set.
const PLACE_CUES = {
  'london': 'GEO-UK', 'britain': 'GEO-UK', 'british': 'GEO-UK', 'north sea': 'GEO-UK',
  'frankfurt': 'GEO-DE', 'berlin': 'GEO-DE', 'munich': 'GEO-DE', 'german': 'GEO-DE',
  'paris': 'GEO-FR', 'toulouse': 'GEO-FR', 'french': 'GEO-FR',
  'dublin': 'GEO-IE', 'irish': 'GEO-IE',
  'amsterdam': 'GEO-NL', 'rotterdam': 'GEO-NL', 'dutch': 'GEO-NL',
  'brussels': 'GEO-EU', 'european commission': 'GEO-EU', 'europe': 'GEO-EU',
  'seoul': 'GEO-KR', 'korean': 'GEO-KR',
  'tokyo': 'GEO-JP', 'japanese': 'GEO-JP',
  'beijing': 'GEO-CN', 'shanghai': 'GEO-CN', 'chinese': 'GEO-CN',
  'mumbai': 'GEO-IN', 'bengaluru': 'GEO-IN', 'bangalore': 'GEO-IN', 'indian': 'GEO-IN',
  'sydney': 'GEO-AU', 'melbourne': 'GEO-AU', 'perth': 'GEO-AU', 'australian': 'GEO-AU',
  'toronto': 'GEO-CA', 'vancouver': 'GEO-CA', 'canadian': 'GEO-CA',
  'sao paulo': 'GEO-BR', 'rio de janeiro': 'GEO-BR', 'brazilian': 'GEO-BR',
  'manhattan': 'GEO-US-NY', 'brooklyn': 'GEO-US-NY',
  'austin': 'GEO-US-TX', 'dallas': 'GEO-US-TX', 'houston': 'GEO-US-TX',
  'palo alto': 'GEO-US-CA', 'san francisco': 'GEO-US-CA', 'los angeles': 'GEO-US-CA',
  'san jose': 'GEO-US-CA', 'santa clara': 'GEO-US-CA', 'sacramento': 'GEO-US-CA',
  'wilmington': 'GEO-US-DE',
  'securities and exchange commission': 'GEO-US', 'commerce department': 'GEO-US',
  'national labor relations board': 'GEO-US', 'u.s.': 'GEO-US',
};
// Every active geography label is itself a cue, so the map above only has to
// carry cities and demonyms the labels do not cover.
for (const v of src.vocab) {
  if (v.facet === 'GEOGRAPHY' && v.status === 'active' && v.label.length >= 5) {
    PLACE_CUES[v.label.toLowerCase()] = v.code;
  }
}

const SUBJECT_CUES = [
  { code: 'SUBJ-REG', re: /\bregulat(?:or|ors|ory)\b|\bsupervisors?\b|\benforcement notice\b|\bsecurities and exchange commission\b|\bnational labor relations board\b|\beuropean commission\b|\bdata protection commission\b|\bcommerce department\b/i, label: 'a regulator, supervisor or enforcement body is named' },
  { code: 'SUBJ-TAX', re: /\bvat\b|\btaxation\b|\btax\b/i, label: 'tax is discussed' },
  { code: 'SUBJ-LIT', re: /\bfederal court\b|\bappeals court\b|\bdistrict court\b|\blawsuit\b|\bsued\b|\bverdict\b|\bcertified a class\b/i, label: 'a court proceeding is described' },
];

// INDUSTRY cues. Added in run 45. Deliberately narrow: only terms that name an
// industry rather than merely touching one. IND-TECH is intentionally absent -
// "platform", "software" and "digital" appear in most business copy, and a cue
// that fires on everything sends everything to review, which is the same as
// having no gate at all while costing editor time.
//
// Methodological caveat, recorded rather than buried: these cues were written
// after seeing which industry tags this eval set missed. Cues fitted to the set
// they are scored on will always look better here than on new copy. They are
// written from what the words mean, not from the specific records, but the only
// honest test is a second labelled set the cues were not designed against.
const INDUSTRY_CUES = [
  { code: 'IND-SEMI', re: /\bsemiconductors?\b|\bchipmakers?\b|\bchip (?:maker|plant|fab|production)\b|\bfoundry\b/i, label: 'semiconductor manufacturing is described' },
  { code: 'IND-INSUR', re: /\binsurers?\b|\binsurance\b|\bhealth plans?\b|\bpolicyholders?\b|\bunderwrit(?:er|ing)\b/i, label: 'an insurer or insurance product is named' },
  { code: 'IND-BANK', re: /\bbanks?\b|\bbanking\b|\blenders?\b|\bcredit union\b/i, label: 'a bank or lender is named' },
  { code: 'IND-AGRI', re: /\bagricultur(?:e|al)\b|\bfarm(?:s|ers|ing|land)?\b|\bcrops?\b|\bpesticides?\b|\bherbicides?\b|\bharvest\b/i, label: 'agriculture or crop production is described' },
  { code: 'IND-RETAIL', re: /\bretailers?\b|\bstorefronts?\b|\be-?commerce\b|\bshoppers?\b|\bcheckout\b/i, label: 'retail or e-commerce activity is described' },
];

// Authority-file industry cross-check. Added in run 46.
//
// Run 45 left exactly one silent error: A14 auto-published with IND-HEALTH but
// without IND-INSUR (and therefore without IND-BANK, which rolls up from it).
// The regex cue above could not catch it, and no regex could: the article never
// uses the words "insurer" or "insurance". It just names Elevance Health. You
// cannot read that industry off the text - you have to know the company.
//
// The pipeline already knows the company. Entity resolution scored 100% precision
// and 100% recall on this set and resolved CO-0012 correctly, including through
// the former-name alias Anthem. What was missing is that the authority file
// carried no industry classification, so the one layer that had the answer was
// never asked. A real company authority file carries SIC or NAICS codes on every
// record; this prototype's stand-in did not.
//
// So: for every entity resolved as PRIMARY, if the authority file says what
// industry it is in and that code was not applied, refuse to auto-publish.
// Primary only - a passing mention must not drag its industry into the record,
// which is the failure mode A17 was built to test.
//
// Two honest limits. This map lives here rather than on the authority record
// because the authority file is defined upstream in Load Article Queue; moving
// it there is the first cleanup, not a redesign. And it deliberately covers only
// single-industry companies. Bayer is pharmaceuticals and chemicals and crop
// science at once, so a single default for it would manufacture false blocks on
// any article about just one of those. A company's registered industry is a
// default, not a statement about what a given story is about.
const ENTITY_INDUSTRY = {
  'CO-0001': 'IND-TECH',
  'CO-0002': 'IND-TECH',
  'CO-0003': 'IND-PHARM',
  'CO-0004': 'IND-BANK',
  'CO-0006': 'IND-SEMI',
  'CO-0009': 'IND-BANK',
  'CO-0010': 'IND-OILGAS',
  'CO-0012': ['IND-HEALTH', 'IND-INSUR'], // Golden 500 v2: a health insurer is filed under both
  'CO-0013': 'IND-TECH',
  'CO-0014': 'IND-SEMI',
  'CO-0015': 'IND-PHARM',
};

const completenessFlags = [];
if (llm_status === 'ok') {
  for (const term of Object.keys(PLACE_CUES)) {
    const code = PLACE_CUES[term];
    if (haystack.indexOf(term) === -1) continue;
    if (appliedGeography.indexOf(code) !== -1) continue;
    if (completenessFlags.find(f => f.expected_code === code)) continue;
    completenessFlags.push({
      facet: 'GEOGRAPHY', expected_code: code, cue: term,
      detail: 'the text mentions "' + term + '" but ' + code + ' was not applied',
    });
  }
  for (const c of SUBJECT_CUES) {
    if (!c.re.test(articleText)) continue;
    if (appliedSubject.indexOf(c.code) !== -1) continue;
    completenessFlags.push({
      facet: 'SUBJECT', expected_code: c.code, cue: c.label,
      detail: c.label + ' but ' + c.code + ' was not applied',
    });
  }
  for (const c of INDUSTRY_CUES) {
    if (!VOCAB_BY_CODE[c.code] || VOCAB_BY_CODE[c.code].status !== 'active') continue;
    if (!c.re.test(articleText)) continue;
    if (appliedIndustry.indexOf(c.code) !== -1) continue;
    completenessFlags.push({
      facet: 'INDUSTRY', expected_code: c.code, cue: c.label,
      detail: c.label + ' but ' + c.code + ' was not applied',
    });
  }
  for (const e of entities) {
    // An entry can name more than one industry (Elevance Health is both a payer and an insurer).
    const mapped = [].concat(ENTITY_INDUSTRY[e.entity_id] || []);
    for (const code of mapped) {
      if (!VOCAB_BY_CODE[code] || VOCAB_BY_CODE[code].status !== 'active') continue;
      if (appliedIndustry.indexOf(code) !== -1) continue;
      if (completenessFlags.find(f => f.expected_code === code)) continue;
      completenessFlags.push({
        facet: 'INDUSTRY', expected_code: code, cue: 'authority file: ' + e.name,
        detail: e.name + ' is a subject of the story and the authority file classifies it as ' +
          VOCAB_BY_CODE[code].label + ', but ' + code + ' was not applied',
      });
    }
  }
}

const allApplied = [].concat(subjects, industries, geographies);
const minConfidence = allApplied.length === 0 ? 0 : Math.min(...allApplied.map(t => t.confidence));

function topConfidence(arr) {
  return arr.length === 0 ? 0 : Math.max(...arr.map(t => t.confidence));
}
const leadByFacet = {
  SUBJECT: topConfidence(subjects),
  INDUSTRY: topConfidence(industries),
  GEOGRAPHY: topConfidence(geographies),
};

const appliedByFacet = { SUBJECT: subjects.length, INDUSTRY: industries.length, GEOGRAPHY: geographies.length };
const emptyRequired = policy.required_facets.filter(f => appliedByFacet[f] === 0);

// Per-facet auto-publish floors, and a recorded negative result.
//
// Run 42 tested dropping the INDUSTRY floor from 0.85 to 0.70, on the argument
// that INDUSTRY posted 100% precision over 23 true positives and caused all four
// unnecessary editor reviews in run 41. Throughput and queue precision both
// improved - straight-through 20.8% to 45.8%, queue precision 76.5% to 90.9% -
// and the headline safety metric got WORSE: silent errors went from 1 of 5 to
// 3 of 11. A14 and A15 auto-published with missing tags the 0.85 floor had been
// holding back.
//
// The reasoning error is worth keeping written down: the floor was gating RECALL,
// not precision. Low model confidence on this facet does not predict a wrong tag,
// it predicts an INCOMPLETE tag set, and a precision table cannot see an omission.
// Run 44 fixed the over-tagging side and the floor went back to 0.85, which cost
// throughput: 16.7% straight-through, with all three unnecessary reviews (A04,
// A17, A23) caused by INDUSTRY lead confidence sitting just under the bar on
// records that were otherwise clean.
//
// Run 45 retried 0.70 after closing the hole that made it unsafe: the INDUSTRY
// facet had NO completeness cues at all, so nothing in the pipeline could notice
// a missing industry tag. With cues in place, 0.70 held - straight-through
// doubled to 33.3% and the only remaining silent error was one the cues could
// not reach. If the silent error count moves off zero, this goes back to 0.85.
//
// These are defaults. auto_publish_min_confidence_by_facet in POLICY overrides
// any of them, so an editorial lead still tunes thresholds as configuration.
const FACET_FLOOR_DEFAULTS = { SUBJECT: 0.85, INDUSTRY: 0.70, GEOGRAPHY: 0.85 };
function facetFloor(f) {
  const m = policy.auto_publish_min_confidence_by_facet || {};
  if (typeof m[f] === 'number') return m[f];
  if (typeof FACET_FLOOR_DEFAULTS[f] === 'number') return FACET_FLOOR_DEFAULTS[f];
  return policy.auto_publish_min_confidence;
}
const weakRequired = policy.required_facets.filter(f =>
  appliedByFacet[f] > 0 && leadByFacet[f] < facetFloor(f));

// LAYER 3C - subject salience gate, v2.
//
// v1 used lede position as the salience proxy and did NOT fire on A01. The
// reason is instructive: A01 is wire copy, about four paragraphs, so the
// antitrust sentence sits inside the first 600 characters along with everything
// else in the story. Lede position only discriminates on long-form articles. On
// the wire it is very nearly a constant, which makes it a useless test exactly
// where most of the volume is.
//
// v2 uses a signal the model already gives us and the pipeline was throwing
// away. On A01 the model returned SUBJ-MNA at 0.97 and SUBJ-ANTI at 0.70. It was
// saying plainly that the second claim is much weaker. The record auto-published
// anyway, because review_floor_confidence (0.60) is the only bar a tag must
// clear to be APPLIED, and auto_publish_min_confidence is tested against the
// LEAD tag of each facet and never against the others. So a 0.70 tag rode into
// the index behind a 0.97 one, and the two numbers the model handed us to tell
// them apart were never compared to each other.
//
// The rule: the lead subject decides what the story is and is governed by the
// facet floor. Every ADDITIONAL subject is a separate claim that the story is
// also about something else, and a claim of that kind has to meet the same bar,
// not the much lower bar for merely being recorded.
//
// Evidence that this is a genuinely marginal judgement rather than a model
// failure: A02 is the same article from a lower-tier outlet, and on that call
// the model scored SUBJ-ANTI at 0.40 and the conformance guard rejected it
// outright. Same text, same prompt, 0.40 and 0.70 on two draws. A judgement that
// unstable does not belong in an index unreviewed.
//
// Note also what the roll-up did here. The model proposed ONE extra code. The
// taxonomy roll-up then added SUBJ-REG as SUBJ-ANTI's broader term, turning one
// marginal model call into two wrong codes in the index. Blocking the parent
// takes the inherited child with it, which is why this gate only examines
// non-inherited tags.
//
// Failing tags are NOT dropped. Silently dropping a tag is the same class of
// error in the other direction, and the completeness gate exists precisely
// because omissions matter too. They route to a human with the reason named.
const salienceCfg = policy.subject_salience || {};
const salienceFlags = [];
if (salienceCfg.enabled !== false && llm_status === 'ok') {
  const secondaryFloor = typeof salienceCfg.secondary_min_confidence === 'number'
    ? salienceCfg.secondary_min_confidence
    : facetFloor('SUBJECT');
  const proposed = subjects
    .filter(t => !t.inherited_from)
    .slice()
    .sort((a, b) => b.confidence - a.confidence);
  for (const t of proposed.slice(1)) {
    if (t.confidence < secondaryFloor) {
      const carried = subjects
        .filter(x => x.inherited_from === t.code)
        .map(x => x.code);
      salienceFlags.push({
        facet: 'SUBJECT',
        code: t.code,
        confidence: t.confidence,
        lead_code: proposed[0].code,
        lead_confidence: proposed[0].confidence,
        carries: carried,
        detail: t.code + ' is a secondary subject at ' + t.confidence +
          ' behind a lead of ' + proposed[0].confidence + ' (' + proposed[0].code +
          '), below the ' + secondaryFloor + ' bar an auto-published claim must meet' +
          (carried.length ? '; would also carry ' + carried.join(', ') + ' into the index by roll-up' : ''),
      });
    }
  }
}

// v3 (Golden 500, exec 69): a tag the model proposed below the 0.60 floor is set aside,
// and until now the record could still publish as if nothing had been said. In exec 69
// 13 of the 27 silent errors were exactly this: the model named the missing code, at
// 0.40-0.55, and the floor dropped it. A doubt the model raised is a reason for a person
// to look, not a reason to publish without it - the same lesson as the compliance
// reviewer's notes. Threshold chosen on the tune half of the Golden 500 (0.40: tune
// 11.9% -> 5.7%), then checked on the holdout half (11.3% -> 6.1%).
const DOUBT_MIN_CONFIDENCE = 0.40;
const DOUBT_FACETS = ['SUBJECT', 'INDUSTRY', 'GEOGRAPHY'];
const appliedAnyFacet = new Set([].concat(subjects, industries, geographies).map(t => t.code));
const doubts = rejections.filter(r =>
  (r.reason === 'BELOW_CONFIDENCE_FLOOR' || r.reason === 'FACET_CAP_EXCEEDED') &&
  DOUBT_FACETS.indexOf(r.facet) !== -1 &&
  typeof r.confidence === 'number' && r.confidence >= DOUBT_MIN_CONFIDENCE &&
  !appliedAnyFacet.has(r.code));

const hardRejections = rejections.filter(r =>
  r.reason === 'HALLUCINATED_CODE' || r.reason === 'UNGROUNDED_EVIDENCE' ||
  r.reason === 'FACET_MISMATCH' || r.reason === 'ENTITY_NOT_IN_CANDIDATES');

let decision;
let decision_reason;

if (llm_status !== 'ok') {
  decision = 'SPECIALIST_REVIEW';
  decision_reason = 'Enrichment layer unavailable - failing safe to a human, never to auto-publish';
} else if (!src.is_canonical) {
  decision = 'DUPLICATE_SUPPRESSED';
  decision_reason = 'Near-duplicate of ' + src.canonical_article_id + ' in cluster ' + src.cluster_id + '; canonical version already indexed';
} else if (hardRejections.length > 0) {
  decision = 'EDITOR_REVIEW';
  decision_reason = 'Guard rejected ' + hardRejections.length + ' proposed tag(s): ' + hardRejections.map(r => r.code + ' (' + r.reason + ')').join(', ');
} else if (emptyRequired.length > 0) {
  decision = 'EDITOR_REVIEW';
  decision_reason = 'Required facet(s) returned no code: ' + emptyRequired.join(', ') + '. Routed for confirmation and logged as a possible taxonomy gap';
} else if (completenessFlags.length > 0) {
  decision = 'EDITOR_REVIEW';
  decision_reason = 'Record looks under-tagged: ' + completenessFlags.map(f => f.expected_code + ' (' + f.cue + ')').join(', ');
} else if (salienceFlags.length > 0) {
  decision = 'EDITOR_REVIEW';
  decision_reason = 'Record looks over-tagged on SUBJECT: ' + salienceFlags.map(f => f.code + ' at ' + f.confidence + ' behind a ' + f.lead_confidence + ' lead' + (f.carries.length ? ' (+' + f.carries.join(', ') + ' by roll-up)' : '')).join(', ') + '. Lead subject stands; weak secondary claims go to a human rather than being published or silently dropped';
} else if (doubts.length > 0) {
  decision = 'EDITOR_REVIEW';
  decision_reason = 'Model raised a tag it was unsure of: ' + doubts.map(d => d.code + ' at ' + d.confidence + ' (below the ' + policy.review_floor_confidence + ' floor)').join(', ') + '. A person decides whether it belongs';
} else if (weakRequired.length > 0) {
  decision = 'EDITOR_REVIEW';
  decision_reason = 'Lead tag confidence below the per-facet auto-publish threshold on: ' + weakRequired.map(f => f + ' (' + leadByFacet[f].toFixed(2) + ' < ' + facetFloor(f) + ')').join(', ');
} else {
  decision = 'AUTO_PUBLISH';
  decision_reason = 'All tags in vocabulary, all evidence verbatim, no completeness cue unmatched, no secondary subject failing salience, lead tag on every required facet at or above its per-facet floor';
}

const cost_usd = (usage.input_tokens / 1e6) * 3 + (usage.output_tokens / 1e6) * 15;

function codesOf(arr) { return arr.map(t => t.code); }

return {
  json: {
    article_id: src.article_id,
    headline: src.headline,
    source: src.source,
    source_tier: src.source_tier,
    trap: src.trap,
    cluster_id: src.cluster_id,
    cluster_size: src.cluster_size,
    is_canonical: src.is_canonical,
    canonical_article_id: src.canonical_article_id,
    decision,
    decision_reason,
    applied: { subjects, industries, geographies, entities },
    applied_codes: {
      SUBJECT: codesOf(subjects),
      INDUSTRY: codesOf(industries),
      GEOGRAPHY: codesOf(geographies),
      COMPANY: entities.map(e => e.entity_id),
    },
    truth_codes: {
      SUBJECT: closure(src.truth_subjects),
      INDUSTRY: closure(src.truth_industries),
      GEOGRAPHY: closure(src.truth_geographies),
      COMPANY: src.truth_entities,
    },
    guard: {
      rejections,
      remaps,
      hard_rejection_count: hardRejections.length,
      proposed_total: llm_status === 'ok'
        ? (parsed.subject_codes || []).length + (parsed.industry_codes || []).length + (parsed.geography_codes || []).length
        : 0,
      applied_total: allApplied.length,
      inherited_total: allApplied.filter(t => t.inherited_from).length,
      min_confidence: Number(minConfidence.toFixed(3)),
      lead_confidence: leadByFacet,
      provisional_tag_count: allApplied.filter(t => t.provisional).length,
    },
    salience: {
      flags: salienceFlags,
      blocked: salienceFlags.length > 0 && hardRejections.length === 0 &&
        emptyRequired.length === 0 && completenessFlags.length === 0,
    },
    completeness: {
      flags: completenessFlags,
      blocked: completenessFlags.length > 0 && hardRejections.length === 0 && emptyRequired.length === 0,
    },
    uncoded_note: llm_status === 'ok' ? (parsed.uncoded_note || '') : '',
    entity_candidates: src.entity_candidates,
    llm_status,
    input_tokens: usage.input_tokens,
    output_tokens: usage.output_tokens,
    cost_usd: Number(cost_usd.toFixed(6)),
    indexed_at: new Date().toISOString(),
  },
};

const rows = $input.all().map(i => i.json);
const FACETS = ['SUBJECT', 'INDUSTRY', 'GEOGRAPHY', 'COMPANY'];

const pct = (n, d) => (d === 0 ? null : Number(((n / d) * 100).toFixed(1)));
const r3 = n => Number(n.toFixed(3));

const scored = rows.filter(r => r.decision !== 'DUPLICATE_SUPPRESSED' && r.llm_status === 'ok');
const suppressed = rows.filter(r => r.decision === 'DUPLICATE_SUPPRESSED');

function hasTagError(r) {
  return FACETS.some(f => {
    const got = (r.applied_codes[f] || []).slice().sort().join('|');
    const want = (r.truth_codes[f] || []).slice().sort().join('|');
    return got !== want;
  });
}

const facetQuality = {};
for (const facet of FACETS) {
  let tp = 0, fp = 0, fn = 0;
  let exact = 0;
  const errors = [];
  for (const r of scored) {
    const got = r.applied_codes[facet] || [];
    const want = r.truth_codes[facet] || [];
    const missed = want.filter(c => !got.includes(c));
    const extra = got.filter(c => !want.includes(c));
    tp += got.filter(c => want.includes(c)).length;
    fp += extra.length;
    fn += missed.length;
    if (missed.length === 0 && extra.length === 0) exact++;
    if (missed.length > 0 || extra.length > 0) {
      errors.push({ article_id: r.article_id, missed, extra, decision: r.decision });
    }
  }
  const precision = tp + fp === 0 ? null : tp / (tp + fp);
  const recall = tp + fn === 0 ? null : tp / (tp + fn);
  const f1 = precision && recall && precision + recall > 0 ? (2 * precision * recall) / (precision + recall) : null;
  facetQuality[facet] = {
    precision_pct: precision === null ? null : Number((precision * 100).toFixed(1)),
    recall_pct: recall === null ? null : Number((recall * 100).toFixed(1)),
    f1: f1 === null ? null : r3(f1),
    exact_set_match_pct: pct(exact, scored.length),
    true_positives: tp, false_positives: fp, false_negatives: fn,
    errors,
  };
}

let proposed = 0, appliedFromModel = 0, inherited = 0;
const byReason = {};
const hallucinated = [];
const ungrounded = [];
const remapped = [];
for (const r of rows) {
  proposed += r.guard.proposed_total;
  inherited += (r.guard.inherited_total || 0);
  appliedFromModel += r.guard.applied_total - (r.guard.inherited_total || 0);
  for (const rej of r.guard.rejections) {
    byReason[rej.reason] = (byReason[rej.reason] || 0) + 1;
    if (rej.reason === 'HALLUCINATED_CODE') hallucinated.push({ article_id: r.article_id, code: rej.code, facet: rej.facet, confidence: rej.confidence });
    if (rej.reason === 'UNGROUNDED_EVIDENCE') ungrounded.push({ article_id: r.article_id, code: rej.code, facet: rej.facet, evidence: rej.evidence });
  }
  for (const rm of r.guard.remaps) remapped.push({ article_id: r.article_id, from: rm.from, to: rm.to });
}

const byDecision = {};
for (const r of rows) byDecision[r.decision] = (byDecision[r.decision] || 0) + 1;

const autoCount = byDecision.AUTO_PUBLISH || 0;
const editorCount = (byDecision.EDITOR_REVIEW || 0) + (byDecision.SPECIALIST_REVIEW || 0);

const silentErrors = [];
for (const r of scored) {
  if (r.decision !== 'AUTO_PUBLISH') continue;
  const wrong = FACETS.filter(f => {
    const got = (r.applied_codes[f] || []).slice().sort().join('|');
    const want = (r.truth_codes[f] || []).slice().sort().join('|');
    return got !== want;
  });
  if (wrong.length > 0) {
    silentErrors.push({
      article_id: r.article_id, facets: wrong, trap: r.trap,
      got: r.applied_codes, expected: r.truth_codes,
    });
  }
}

// What the completeness layer bought, and what it cost.
// A record it blocked that had no tag error is an editor minute spent for
// nothing; a record it blocked that did have one is a silent error prevented.
const blocked = scored.filter(r => r.completeness && r.completeness.blocked);
const blockedWithError = blocked.filter(hasTagError);
const blockedClean = blocked.filter(r => !hasTagError(r));

const reviewJustified = [];
const reviewUnnecessary = [];
for (const r of scored) {
  if (r.decision !== 'EDITOR_REVIEW' && r.decision !== 'SPECIALIST_REVIEW') continue;
  const rec = { article_id: r.article_id, why: r.decision_reason, trap: r.trap };
  if (hasTagError(r)) reviewJustified.push(rec); else reviewUnnecessary.push(rec);
}

const taxonomyGaps = rows
  .filter(r => r.uncoded_note && String(r.uncoded_note).trim().length > 0)
  .map(r => ({ article_id: r.article_id, note: r.uncoded_note }));

const totalCost = rows.reduce((s, r) => s + (r.cost_usd || 0), 0);
const dupCost = suppressed.reduce((s, r) => s + (r.cost_usd || 0), 0);
const errorRows = rows.filter(r => r.llm_status !== 'ok');

const entityTrapA08 = rows.find(r => r.article_id === 'A08');
const entityTrapA17 = rows.find(r => r.article_id === 'A17');

return [{
  json: {
    run_at: new Date().toISOString(),
    records_ingested: rows.length,
    records_enriched_and_scored: scored.length,

    routing: {
      by_decision: byDecision,
      straight_through_pct: pct(autoCount, rows.length),
      editor_touch_pct: pct(editorCount, rows.length),
      note: 'Straight-through rate is the throughput number. Editor touch rate is the cost number. Neither means anything without the silent error count below.',
    },

    headline_safety_metric: {
      auto_published_with_tag_errors: silentErrors.length,
      auto_published_total: autoCount,
      silent_error_rate_pct: pct(silentErrors.length, autoCount),
      detail: silentErrors,
      note: 'The only errors that reach a customer are the ones that auto-published. Every other error was caught by a human or by the guard.',
    },

    completeness_gate: {
      records_blocked: blocked.length,
      silent_errors_prevented: blockedWithError.length,
      blocked_but_actually_clean: blockedClean.length,
      precision_pct: pct(blockedWithError.length, blocked.length),
      prevented_detail: blockedWithError.map(r => ({ article_id: r.article_id, flags: r.completeness.flags.map(f => f.expected_code + ' <- ' + f.cue) })),
      cost_detail: blockedClean.map(r => ({ article_id: r.article_id, flags: r.completeness.flags.map(f => f.expected_code + ' <- ' + f.cue) })),
      note: 'Deterministic cues that detect under-tagging. They never add a tag, so precision is unaffected - they convert silent errors into editor reviews. silent_errors_prevented is the benefit, blocked_but_actually_clean is the bill.',
    },

    taxonomy_conformance: {
      codes_proposed_by_model: proposed,
      codes_accepted_from_model: appliedFromModel,
      codes_inherited_from_taxonomy: inherited,
      rejection_rate_pct: pct(proposed - appliedFromModel, proposed),
      rejections_by_reason: byReason,
      hallucinated_codes: hallucinated,
      ungrounded_evidence: ungrounded,
      deprecated_remaps: remapped,
      note: 'A code that is not in the vocabulary cannot enter the index, whatever the model returns. Evidence spans are checked verbatim against the source text, so a confident but fabricated justification is caught deterministically and for free.',
    },

    facet_quality: facetQuality,

    review_queue_quality: {
      justified: reviewJustified.length,
      unnecessary: reviewUnnecessary.length,
      precision_of_review_queue_pct: pct(reviewJustified.length, reviewJustified.length + reviewUnnecessary.length),
      unnecessary_detail: reviewUnnecessary,
      note: 'Records routed to a human that a human would not have changed. Drives the threshold down when it is high.',
    },

    entity_resolution: {
      shell_disambiguation_A08: entityTrapA08
        ? { resolved_entities: entityTrapA08.applied_codes.COMPANY, expected: [], passed: entityTrapA08.applied_codes.COMPANY.length === 0 }
        : null,
      passing_mention_A17: entityTrapA17
        ? { resolved_entities: entityTrapA17.applied_codes.COMPANY, expected: ['CO-0001'], passed: entityTrapA17.applied_codes.COMPANY.length === 1 && entityTrapA17.applied_codes.COMPANY[0] === 'CO-0001' }
        : null,
      note: 'A08 contains the word "shell" but no Shell plc. A17 mentions Microsoft only as a former employer.',
    },

    deduplication: {
      clusters_detected: new Set(rows.map(r => r.cluster_id)).size,
      duplicates_suppressed: suppressed.length,
      duplicate_rate_pct: pct(suppressed.length, rows.length),
      suppressed_detail: suppressed.map(r => ({ article_id: r.article_id, duplicate_of: r.canonical_article_id, source: r.source })),
      note: 'Duplicates were enriched in this prototype so the cost could be measured. Moving the dedup gate ahead of the model call removes that spend entirely.',
    },

    taxonomy_gap_report: {
      articles_with_uncoded_concepts: taxonomyGaps.length,
      detail: taxonomyGaps,
      note: 'Standing input to taxonomy governance. Repeated gaps are the case for a new code, evidenced rather than asserted.',
    },

    reliability: {
      enrichment_errors: errorRows.length,
      error_rate_pct: pct(errorRows.length, rows.length),
      errored_articles: errorRows.map(r => ({ article_id: r.article_id, status: r.llm_status })),
      note: 'Every errored record routes to a human. The pipeline has no path from failure to auto-publish.',
    },

    unit_economics: {
      total_usd: Number(totalCost.toFixed(4)),
      per_article_usd: Number((totalCost / rows.length).toFixed(6)),
      projected_usd_per_1000_articles: Number(((totalCost / rows.length) * 1000).toFixed(2)),
      wasted_on_duplicates_usd: Number(dupCost.toFixed(4)),
      input_tokens: rows.reduce((s, r) => s + (r.input_tokens || 0), 0),
      output_tokens: rows.reduce((s, r) => s + (r.output_tokens || 0), 0),
    },
  },
}];

const s = $input.first().json;

// Everything the brief is permitted to assert, extracted deterministically from
// the scorecard. The narrative layer downstream is handed ONLY this object and
// is forbidden from introducing figures of its own - the same discipline the
// tagging path applies to codes. A brief that invents a number is worse than no
// brief, because a stakeholder cannot tell the difference by reading it.
const facts = {
  run_at: s.run_at,
  records_ingested: s.records_ingested,
  records_scored: s.records_enriched_and_scored,
  routing: s.routing,
  safety: s.headline_safety_metric,
  completeness_gate: s.completeness_gate,
  taxonomy_conformance: s.taxonomy_conformance,
  facet_quality: s.facet_quality,
  review_queue_quality: s.review_queue_quality,
  entity_resolution: s.entity_resolution,
  deduplication: s.deduplication,
  taxonomy_gap_report: s.taxonomy_gap_report,
  reliability: s.reliability,
  unit_economics: s.unit_economics,
};

// Trim the long per-record arrays before they reach the prompt. The document
// renders the full lists from facts; the narrative only needs enough to reason.
const compact = JSON.parse(JSON.stringify(facts));
for (const f of Object.keys(compact.facet_quality)) {
  compact.facet_quality[f].errors = (compact.facet_quality[f].errors || []).slice(0, 6);
}
if (compact.safety && compact.safety.detail) {
  compact.safety.detail = compact.safety.detail.slice(0, 5);
}

const prompt =
  'You are the content operations lead who designed and ran this news metadata enrichment pipeline. ' +
  'Write the narrative sections of a run brief for an editorial director and their engineering counterpart. ' +
  'They are technical enough to read a precision figure but they do not know how this pipeline is built.\n\n' +
  'HOW THE PIPELINE WORKS\n' +
  'Incoming news articles are deduplicated at ingest, scanned against a company authority file, then sent to a language model that proposes controlled-vocabulary codes for subject, industry and geography, each with a confidence and a verbatim evidence span. ' +
  'A deterministic conformance guard then rejects any code that is not in the vocabulary, is in the wrong facet, quotes evidence that does not appear in the article, uses a retired code, or falls below a confidence floor. ' +
  'A second deterministic layer checks for UNDER-tagging using place-name and regulator cues, and blocks auto-publish when a cue fires and its code is absent. ' +
  'Records then route to auto-publish, editor review, specialist review, or duplicate-suppressed. ' +
  'Every record carries an editor-assigned answer key so the run can score itself.\n\n' +
  'ABSOLUTE RULES\n' +
  '1. Use ONLY figures that appear in the RUN DATA below. Never estimate, never round differently, never infer a number that is not there.\n' +
  '2. If you want to make a point that the data does not support, do not make it.\n' +
  '3. The silent error rate is the headline safety metric: records that auto-published and did not match the key. Errors caught by a human or by a guard are the system working, not failures.\n' +
  '4. Be direct about weaknesses. This brief is read by people deciding whether to trust the pipeline, and a brief that only reports good news is worthless to them.\n' +
  '5. Remember the sample is small. Do not present figures from this run as if they were stable production measurements.\n\n' +
  'RUN DATA\n' + JSON.stringify(compact, null, 2) + '\n\n' +
  'Respond with ONLY valid JSON, no preamble and no code fences, in exactly this shape:\n' +
  '{"one_line_summary":"a single sentence a director could forward with no other context",' +
  '"verdict":"two to four sentences on whether this run is trustworthy and what the single most important number is",' +
  '"proven":["a specific capability this run demonstrated, tied to a figure or a named record"],' +
  '"not_proven":["a specific thing this run does NOT establish, and why"],' +
  '"notable_records":[{"article_id":"A00","what_happened":"one sentence","why_it_matters":"one sentence"}],' +
  '"recommended_actions":[{"priority":"High|Medium|Low","action":"an imperative instruction","rationale":"one sentence citing the figure that motivates it"}]}\n' +
  'Aim for 3-5 items in proven, 3-5 in not_proven, 3-5 notable_records, and 4-6 recommended_actions ordered most to least important.';

return [{ json: { facts, prompt } }];

const facts = $('Compose Brief Inputs').first().json.facts;
const resp = $input.first().json;

let parsed = null;
let narrative_status = 'ok';
try {
  if (resp.error) throw new Error(resp.error.message || 'api error');
  const blocks = Array.isArray(resp.content) ? resp.content : [];
  const tb = blocks.find(b => b && b.type === 'text');
  if (!tb || !tb.text) throw new Error('no text block in response');
  const cleaned = tb.text.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  narrative_status = 'error: ' + e.message;
}

// Fail safe the same way the tagging path does: if the narrative layer is
// unavailable the document still ships, carrying every measured figure and
// saying plainly that the prose is missing. A silently thinner brief would be
// worse than an obviously incomplete one.
const N = parsed || {
  one_line_summary: 'Narrative generation was unavailable on this run. All measured figures below are unaffected.',
  verdict: 'The narrative layer failed (' + narrative_status + '). Every number in this document is taken directly from the run scorecard and is complete; only the written analysis is missing.',
  proven: [], not_proven: [], notable_records: [], recommended_actions: [],
};

function esc(x) {
  return String(x === null || x === undefined ? '' : x)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function pc(v) { return (v === null || v === undefined) ? 'n/a' : v + '%'; }
function bullets(arr) {
  if (!arr || arr.length === 0) return '<p class="muted">Not generated on this run.</p>';
  return '<ul>' + arr.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>';
}

const fq = facts.facet_quality;
const facetRows = ['COMPANY', 'GEOGRAPHY', 'INDUSTRY', 'SUBJECT'].filter(f => fq[f]).map(f =>
  '<tr><td><b>' + f + '</b></td><td class="n">' + pc(fq[f].precision_pct) + '</td><td class="n">' +
  pc(fq[f].recall_pct) + '</td><td class="n">' + (fq[f].f1 === null ? 'n/a' : fq[f].f1) + '</td><td class="n">' +
  pc(fq[f].exact_set_match_pct) + '</td><td class="n">' + fq[f].false_positives + ' / ' + fq[f].false_negatives + '</td></tr>'
).join('');

const routingRows = Object.keys(facts.routing.by_decision).map(k =>
  '<tr><td>' + esc(k.replace(/_/g, ' ')) + '</td><td class="n">' + facts.routing.by_decision[k] + '</td></tr>'
).join('');

const cg = facts.completeness_gate || {};
const tc = facts.taxonomy_conformance || {};
const rq = facts.review_queue_quality || {};
const ue = facts.unit_economics || {};
const er = facts.entity_resolution || {};

const silentRows = (facts.safety.detail || []).length === 0
  ? '<tr><td colspan="3" class="muted">None. Every auto-published record matched the editor key.</td></tr>'
  : facts.safety.detail.map(d =>
      '<tr><td><b>' + esc(d.article_id) + '</b></td><td>' + esc((d.facets || []).join(', ')) +
      '</td><td>' + esc(d.trap || '') + '</td></tr>').join('');

const preventedRows = (cg.prevented_detail || []).length === 0
  ? '<tr><td colspan="2" class="muted">No records were held back by the completeness layer.</td></tr>'
  : cg.prevented_detail.map(d =>
      '<tr><td><b>' + esc(d.article_id) + '</b></td><td>' + esc((d.flags || []).join('; ')) + '</td></tr>').join('');

const gapRows = (facts.taxonomy_gap_report.detail || []).length === 0
  ? '<tr><td colspan="2" class="muted">No taxonomy gaps reported on this run.</td></tr>'
  : facts.taxonomy_gap_report.detail.map(g =>
      '<tr><td><b>' + esc(g.article_id) + '</b></td><td>' + esc(g.note) + '</td></tr>').join('');

const notableRows = (N.notable_records || []).length === 0
  ? '<tr><td colspan="3" class="muted">Not generated on this run.</td></tr>'
  : N.notable_records.map(r =>
      '<tr><td><b>' + esc(r.article_id) + '</b></td><td>' + esc(r.what_happened) + '</td><td>' + esc(r.why_it_matters) + '</td></tr>').join('');

const actionRows = (N.recommended_actions || []).length === 0
  ? '<tr><td colspan="3" class="muted">Not generated on this run.</td></tr>'
  : N.recommended_actions.map(a =>
      '<tr><td><b>' + esc(a.priority) + '</b></td><td>' + esc(a.action) + '</td><td>' + esc(a.rationale) + '</td></tr>').join('');

const shellPass = er.shell_disambiguation_A08 ? (er.shell_disambiguation_A08.passed ? 'PASS' : 'FAIL') : 'n/a';
const passingPass = er.passing_mention_A17 ? (er.passing_mention_A17.passed ? 'PASS' : 'FAIL') : 'n/a';

const runDate = new Date(facts.run_at);
const stamp = runDate.toISOString().replace('T', ' ').slice(0, 16) + ' UTC';
const fileStamp = runDate.toISOString().slice(0, 10) + '-' + runDate.toISOString().slice(11, 16).replace(':', '');

const html =
'<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">' +
'<head><meta charset="utf-8"><title>Metadata Agent Run Brief</title>' +
'<!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom></w:WordDocument></xml><![endif]-->' +
'<style>' +
'body{font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#1a1a1a;line-height:1.45;}' +
'h1{font-family:Georgia,serif;font-size:22pt;margin:0 0 4pt 0;}' +
'h2{font-family:Georgia,serif;font-size:14pt;margin:22pt 0 6pt 0;border-bottom:1pt solid #999;padding-bottom:3pt;}' +
'h3{font-size:11.5pt;margin:14pt 0 4pt 0;}' +
'p{margin:0 0 8pt 0;}' +
'.sub{color:#555;font-size:10pt;margin:0 0 14pt 0;}' +
'.lead{font-family:Georgia,serif;font-size:12.5pt;font-style:italic;color:#222;border-left:3pt solid #2f3f86;padding-left:10pt;margin:0 0 14pt 0;}' +
'table{border-collapse:collapse;width:100%;margin:6pt 0 10pt 0;font-size:10pt;}' +
'th{background:#eef1f7;text-align:left;padding:5pt 7pt;border:0.5pt solid #b9c1d1;font-size:9pt;text-transform:uppercase;letter-spacing:0.5pt;}' +
'td{padding:5pt 7pt;border:0.5pt solid #ccd2de;vertical-align:top;}' +
'td.n{text-align:right;white-space:nowrap;}' +
'.muted{color:#666;font-style:italic;}' +
'ul{margin:0 0 10pt 0;padding-left:18pt;}' +
'li{margin-bottom:5pt;}' +
'.foot{margin-top:20pt;padding-top:8pt;border-top:1pt solid #999;font-size:9pt;color:#555;}' +
'</style></head><body>' +
'<h1>Metadata Enrichment Agent</h1>' +
'<p class="sub">Run brief &nbsp;|&nbsp; ' + esc(stamp) + ' &nbsp;|&nbsp; ' + facts.records_ingested + ' records ingested, ' + facts.records_scored + ' enriched and scored</p>' +
'<p class="lead">' + esc(N.one_line_summary) + '</p>' +

'<h2>Verdict</h2><p>' + esc(N.verdict) + '</p>' +

'<h2>Headline measures</h2>' +
'<table><tr><th>Measure</th><th>Value</th><th>What it counts</th></tr>' +
'<tr><td>Straight-through rate</td><td class="n"><b>' + pc(facts.routing.straight_through_pct) + '</b></td><td>Records published with no human touch.</td></tr>' +
'<tr><td>Editor touch rate</td><td class="n"><b>' + pc(facts.routing.editor_touch_pct) + '</b></td><td>Records routed to a human. The operating cost line.</td></tr>' +
'<tr><td>Silent error rate</td><td class="n"><b>' + pc(facts.safety.silent_error_rate_pct) + '</b></td><td>' + facts.safety.auto_published_with_tag_errors + ' of ' + facts.safety.auto_published_total + ' auto-published records differed from the editor key. The only errors with no human in front of them.</td></tr>' +
'<tr><td>Review queue precision</td><td class="n"><b>' + pc(rq.precision_of_review_queue_pct) + '</b></td><td>' + rq.justified + ' of ' + (rq.justified + rq.unnecessary) + ' routed records genuinely needed a human.</td></tr>' +
'<tr><td>Enrichment failures</td><td class="n"><b>' + facts.reliability.enrichment_errors + '</b></td><td>Failures route to specialist review; there is no path from error to auto-publish.</td></tr>' +
'<tr><td>Cost per 1,000 articles</td><td class="n"><b>$' + ue.projected_usd_per_1000_articles + '</b></td><td>Model cost only. Excludes editor minutes, which dominate.</td></tr>' +
'</table>' +

'<h2>What this run proves</h2>' + bullets(N.proven) +

'<h2>What this run does not establish</h2>' + bullets(N.not_proven) +

'<h2>Quality against the editor key</h2>' +
'<table><tr><th>Facet</th><th>Precision</th><th>Recall</th><th>F1</th><th>Exact set</th><th>FP / FN</th></tr>' + facetRows + '</table>' +
'<p class="muted">Precision is the share of applied codes the key agrees with. Recall is the share of key codes that were applied. Recall being the weaker axis is the intended trade: the confidence floor, evidence check and vocabulary test all give up recall to protect precision.</p>' +

'<h2>Guard activity</h2>' +
'<table><tr><th>Check</th><th>Count</th></tr>' +
'<tr><td>Codes proposed by the model</td><td class="n">' + tc.codes_proposed_by_model + '</td></tr>' +
'<tr><td>Accepted from the model</td><td class="n">' + tc.codes_accepted_from_model + '</td></tr>' +
'<tr><td>Broader terms inherited from the taxonomy</td><td class="n">' + tc.codes_inherited_from_taxonomy + '</td></tr>' +
'<tr><td>Rejection rate</td><td class="n">' + pc(tc.rejection_rate_pct) + '</td></tr>' +
'<tr><td>Hallucinated codes rejected</td><td class="n">' + (tc.hallucinated_codes || []).length + '</td></tr>' +
'<tr><td>Ungrounded evidence rejected</td><td class="n">' + (tc.ungrounded_evidence || []).length + '</td></tr>' +
'<tr><td>Retired codes remapped</td><td class="n">' + (tc.deprecated_remaps || []).length + '</td></tr>' +
'</table>' +

'<h2>Completeness layer</h2>' +
'<p>The conformance guard can only test tags that are present. This layer detects under-tagging from place-name and regulator cues and withholds auto-publish. It never adds a tag, so precision is unaffected and the entire cost is paid in editor time.</p>' +
'<table><tr><th>Measure</th><th>Value</th></tr>' +
'<tr><td>Records blocked from auto-publish</td><td class="n">' + cg.records_blocked + '</td></tr>' +
'<tr><td>Silent errors prevented</td><td class="n">' + cg.silent_errors_prevented + '</td></tr>' +
'<tr><td>Blocked but actually clean (false alarms)</td><td class="n">' + cg.blocked_but_actually_clean + '</td></tr>' +
'<tr><td>Gate precision</td><td class="n">' + pc(cg.precision_pct) + '</td></tr>' +
'</table>' +
'<table><tr><th>Record</th><th>Cue that fired</th></tr>' + preventedRows + '</table>' +

'<h2>Errors that reached auto-publish</h2>' +
'<table><tr><th>Record</th><th>Facet</th><th>What the record was testing</th></tr>' + silentRows + '</table>' +

'<h2>Entity resolution checks</h2>' +
'<table><tr><th>Check</th><th>Result</th><th>Why it is in the set</th></tr>' +
'<tr><td>A08 &mdash; "shell companies"</td><td class="n"><b>' + shellPass + '</b></td><td>The word "shell" must not resolve to Shell plc.</td></tr>' +
'<tr><td>A17 &mdash; passing mention</td><td class="n"><b>' + passingPass + '</b></td><td>Microsoft appears only as a former employer and must not be tagged as a subject.</td></tr>' +
'</table>' +

'<h2>Deduplication</h2>' +
'<p>' + facts.deduplication.duplicates_suppressed + ' of ' + facts.records_ingested + ' records (' + pc(facts.deduplication.duplicate_rate_pct) + ') were suppressed as near-duplicates of a higher-tier original, across ' + facts.deduplication.clusters_detected + ' detected story clusters. In production the dedup gate moves ahead of the model call, removing that spend entirely.</p>' +

'<h2>Taxonomy gaps surfaced</h2>' +
'<table><tr><th>Record</th><th>Concept with no code</th></tr>' + gapRows + '</table>' +
'<p class="muted">Standing input to taxonomy governance. A repeated gap is an evidenced case for a new code rather than an opinion in a meeting.</p>' +

'<h2>Notable records</h2>' +
'<table><tr><th>Record</th><th>What happened</th><th>Why it matters</th></tr>' + notableRows + '</table>' +

'<h2>Recommended next actions</h2>' +
'<table><tr><th>Priority</th><th>Action</th><th>Rationale</th></tr>' + actionRows + '</table>' +

'<div class="foot">' +
'<p><b>How this brief was produced.</b> Every figure above is read directly from the run scorecard by deterministic code. The written sections were drafted by a language model that was given those figures and nothing else, and was explicitly forbidden from introducing numbers of its own &mdash; the same separation the tagging pipeline applies to codes. Narrative status on this run: ' + esc(narrative_status) + '.</p>' +
'<p><b>Read this with the sample size in mind.</b> ' + facts.records_ingested + ' records is a prototype, not a production measurement. One record moving changes the silent error rate by more than ten points. These figures are useful for finding architectural gaps and are not yet useful for setting service levels.</p>' +
'</div></body></html>';

return [{
  json: {
    document_html: html,
    document_filename: 'metadata-agent-run-brief-' + fileStamp + '.doc',
    narrative_status,
    one_line_summary: N.one_line_summary,
    verdict: N.verdict,
    proven: N.proven,
    not_proven: N.not_proven,
    notable_records: N.notable_records,
    recommended_actions: N.recommended_actions,
    brief_chars: html.length,
  },
}];

// One compact record per article in the eval harness's shape, for exporting a run.
// Layer 3's items carry the article body and the whole vocabulary, which makes a run slow
// to pull. This node carries only what the harness scores: the route, which rung of the
// routing ladder decided it, each facet's values with confidence (applied and rejected),
// and the answer key. Same translation as the harness repo's
// examples/metadata-enrichment/adapter.js.
const FACETS = { SUBJECT: 'subjects', INDUSTRY: 'industries', GEOGRAPHY: 'geographies', COMPANY: 'entities' };

// Layer 3's routing ladder, identified by the start of each decision_reason. If a reason
// is reworded, this stops the run loudly rather than misfiling records.
const BRANCHES = [
  ['model-failed', /^Enrichment layer unavailable/],
  ['duplicate', /^Near-duplicate of/],
  ['hard-rejection', /^Guard rejected/],
  ['empty-required', /^Required facet\(s\) returned no code/],
  ['completeness', /^Record looks under-tagged/],
  ['salience', /^Record looks over-tagged/],
  ['doubt', /^Model raised a tag it was unsure of/],
  ['gate', /^Lead tag confidence below the per-facet auto-publish threshold/],
  ['auto', /^All tags in vocabulary/],
];

return $input.all().map(({ json: r }) => {
  const branch = BRANCHES.find(([, re]) => re.test(r.decision_reason));
  if (!branch) throw new Error(r.article_id + ': unrecognised decision_reason "' + String(r.decision_reason).slice(0, 60) + '"');
  const output = {};
  for (const [facet, key] of Object.entries(FACETS)) {
    const applied = (r.applied[key] || []).map(t => {
      const v = { value: facet === 'COMPANY' ? t.entity_id : t.code, confidence: t.confidence };
      if (t.inherited_from) v.inherited_from = t.inherited_from;
      return v;
    });
    const appliedCodes = new Set(applied.map(v => v.value));
    // A code the guard rejected as the model's own proposal can still be applied as a
    // narrower code's broader term; the applied copy is what reached the index.
    const rejected = new Map();
    for (const x of r.guard.rejections) {
      if (x.facet !== facet || appliedCodes.has(x.code) || rejected.has(x.code)) continue;
      rejected.set(x.code, { value: x.code, confidence: typeof x.confidence === 'number' ? x.confidence : null, applied: false });
    }
    output[facet] = [...applied, ...rejected.values()];
  }
  return { json: {
    id: r.article_id,
    decision: r.decision,
    decision_branch: branch[0],
    scored: r.llm_status === 'ok',
    trap: r.trap,
    output,
    expected: r.truth_codes,
  } };
});
